"""Small offline implementation of zizmor's artipacked workflow audit.

The module is deliberately independent of the command line and accepts the
normalized input records produced by input_collection.collect().
"""

import re


def audit_artipacked(record):
    """Return json-v1 artipacked findings for a normalized input record."""
    get = record.get if isinstance(record, dict) else lambda k, default=None: getattr(record, k, default)
    is_action = get("kind") in ("action", "actions")
    if get("kind") not in ("workflow", "workflows", "action", "actions"):
        return []
    text = get("text", "")
    path = get("path", "")
    if is_action and not re.search(r"(?m)^\s+using\s*:\s*['\"]?composite\b", text):
        return []
    lines = text.splitlines(keepends=True)
    findings = []
    job = None
    steps_index = -1
    in_steps = False
    in_jobs = False
    current_step = None
    step_has_checkout = False
    step_configured = False
    with_indent = None

    def finish_step():
        if current_step is None or not step_has_checkout or step_configured:
            return
        line_no, column, end_column, raw, ref = current_step
        offset = sum(len(s) for s in lines[:line_no])
        if is_action:
            route = [{"Key": "runs"}, {"Key": "steps"}, {"Index": steps_index}]
        else:
            route = [{"Key": "jobs"}, {"Key": job or ""}, {"Key": "steps"}, {"Index": steps_index}]
        source_line = lines[line_no].rstrip("\r\n")
        feat = lines[line_no][column:]
        comment = None
        quote = None
        for i, char in enumerate(raw):
            if quote:
                if char == quote and (i == 0 or raw[i - 1] != "\\"):
                    quote = None
            elif char in ("'", '"'):
                quote = char
            elif char == "#" and (i == 0 or raw[i - 1].isspace()):
                comment = raw[i:].strip()
                break
        if lines[line_no].endswith(("\n", "\r")):
            end_point = {"row": line_no + 1, "column": 0}
            absolute_end = offset + len(lines[line_no])
        else:
            end_point = {"row": line_no, "column": len(source_line)}
            absolute_end = offset + len(source_line)
        v6 = bool(re.search(r"@v([6-9]|[1-9][0-9]+)(?:\.|$)", ref, re.I))
        findings.append({
            "ident": "artipacked",
            "desc": "credential persistence through GitHub Actions artifacts",
            "url": "https://docs.zizmor.sh/audits/#artipacked",
            "determinations": {"confidence": "Low", "severity": "Low" if v6 else "Medium", "persona": "Regular"},
            "locations": [{
                "symbolic": {
                    "key": {"Stdin": {}} if path in ("-", "<stdin>") else {"Local": {"prefix": None, "given_path": path}},
                    "annotation": "does not set persist-credentials: false",
                    "route": {"route": route}, "feature_kind": "Normal", "kind": "Primary",
                },
                "concrete": {
                    "location": {
                        "start_point": {"row": line_no, "column": column},
                        "end_point": end_point,
                        "offset_span": {"start": offset + column, "end": absolute_end},
                    },
                    "feature": feat, "comments": [comment] if comment else [],
                },
            }],
            "ignored": False,
        })

    for n, rawline in enumerate(lines):
        line = rawline.rstrip("\r\n")
        indent = len(line) - len(line.lstrip(" "))
        m = re.match(r"\s*([\w.-]+):\s*(?:#.*)?$", line)
        if not is_action and indent == 0 and line.strip() == "jobs:":
            finish_step()
            current_step = None
            in_jobs = True
            in_steps = False
            job = None
        elif indent == 0 and m and m.group(1) != "jobs":
            finish_step()
            current_step = None
            job = None
            in_steps = False
            in_jobs = False
        if in_jobs and indent == 2 and m and m.group(1) != "steps":
            finish_step()
            current_step = None
            job = m.group(1)
            step_has_checkout = False
            step_configured = False
            with_indent = None
            steps_index = -1
        if (not is_action and indent == 4 or is_action and indent == 2) and line.strip() == "steps:":
            finish_step()
            current_step = None
            in_steps = True
        step_indent = 4 if is_action else 6
        if in_steps and indent == step_indent and re.match(r"-\s", line.lstrip()):
            finish_step()
            steps_index += 1
            current_step = None
            step_has_checkout = False
            step_configured = False
            with_indent = None
        if in_steps and current_step is None:
            u = re.search(r"\buses:\s*['\"]?(actions/checkout(?:@[^\s#'\"]*)?)", line)
            if u:
                step_has_checkout = True
                key_start = line.rfind("uses:", 0, u.start() + 1)
                if key_start < 0:
                    key_start = u.start()
                current_step = (n, key_start, u.end(), line, u.group(1))
        if in_steps:
            content = line.split("#", 1)[0]
            with_match = re.match(r"^(\s*)with\s*:\s*(.*)$", content, re.I)
            if with_match:
                rest = with_match.group(2).strip()
                if rest.startswith("{"):
                    configured = re.search(r"\bpersist-credentials:\s*([^,}#]*)", rest, re.I)
                    with_indent = None
                else:
                    with_indent = len(with_match.group(1)) if not rest else None
                    configured = None
            elif with_indent is not None and line.strip() and indent <= with_indent:
