                configured = None
            elif with_indent is not None and indent > with_indent:
                configured = re.match(r"^\s+persist-credentials\s*:\s*([^#]*)", content, re.I)
            else:
                configured = None
            if configured:
                value = configured.group(1).strip().strip("'\"").lower()
                if value and value not in ("null", "~"):
                    step_configured = True
    finish_step()
    return findings

